head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.fn_GetPar, scwin.fn_SetPar, scwin.strSch;
scwin.MSG_LOW_CTG_ALW = "표준산업업종 중 소분류 항목만 선택가능합니다.";
scwin.vScrenID = "ULDSTF92006.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listIndustry&inputMessageId=INDUSTRY_INOUT&" + "&IND_NM=" + txb_Search.getValue();
    dts_IndustryList.DataID = encodeURI(url);
    dts_IndustryList.reset();
};
scwin.dts_IndustryList_OnLoadError = function() {
    $c.stf.alert_error(dts_IndustryList);
};
scwin.dts_IndustryList_OnLoadCompleted = function(rowcount) {
    var arrPar = new Array();
    if (dts_IndustryList.errorMsg) {
        $c.win.alert(dts_IndustryList.errorMsg);
    } else {
        txb_TotCnt.setValue("총 " + rowcount + " 건");

        /*
		if (js_market == '2') {
MxGrid_1.setColumnProp("STD_IND_CD", "Show",false) ;
MxGrid_1.setColumnProp("KOSDAQ_STD_IND_CD", "Show",true) ;
		} else if (js_market == '1') {
MxGrid_1.setColumnProp("STD_IND_CD", "Show",true) ;
MxGrid_1.setColumnProp("KOSDAQ_STD_IND_CD", "Show",false) ;
MxGrid_1.setColumnProp('STD_IND_CD','Mask',"XX-XX-XX") ;
		}
		*/
        $c.cm.setColumnProp(MxGrid_1, 'STD_IND_CD', 'Mask', "XX-XX-XX");

        // 초기1회 초기값으로 설정된 업종코드를 검색한다.
        if (scwin.strSch != "") {
            for (var i = 1; i <= dts_IndustryList.getTotalRow(); i++) {
                if (scwin.strSch == dts_IndustryList.getCellData(i, 1)) {
                    // 찾아야할 코드를 발견했을 경우
                    dts_IndustryList.setRowPosition(i, 0);
                    break;
                }
            }
        }
    }
};
scwin.img_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.txb_Search_onkeydown = function() {
    if (event.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.MxGrid_1_OnDblClick = async function(row, colid) {
    var arrPar = new Array();
    var gRow = dts_IndustryList.getRowPosition();
    var gVal = "";

    /*
    	if ( js_market == '1' ) {

    		gVal = dts_IndustryList.NameValue(gRow, "STD_IND_CD");
    		if ( gVal.substr(4, 2) == "00" ) {
    			alert( MSG_LOW_CTG_ALW );
    			return;
    		}

    	} else if  (js_market == '2' ) {

    		gVal = dts_IndustryList.NameValue(row, "KOSDAQ_STD_IND_CD");
    		if (gVal.length != 7 ) {
    			alert( MSG_LOW_CTG_ALW );
    			return;
    		}
    	}
    */
    gVal = dts_IndustryList.getCellData(gRow, "STD_IND_CD");
    if (gVal.substr(4, 2) == "00") {
        $c.win.alert(scwin.MSG_LOW_CTG_ALW);
        return;
    }
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = {
            STD_IND_CD: dts_IndustryList.getCellData(gRow, "STD_IND_CD"),
            IND_NM: dts_IndustryList.getCellData(gRow, "IND_NM")
            //,KOSDAQ_STD_IND_CD: dts_IndustryList.NameValue(gRow, "KOSDAQ_STD_IND_CD")	
        };
        scwin.fn_SetPar(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var arrPar = new Array();
    window.document.body.scroll = "no";

    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    scwin.fn_GetPar = $c.frame.path("../").scwin.fn_GetPar;
    scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
        scwin.strSch = (arrPar.length > 1 ? arrPar[0] : "");
    }
    scwin.fn_list_sync();
};
